import React, { useState, useEffect } from "react";
import * as Survey from "survey-react";
import "survey-react/survey.css"; // Make sure to import SurveyJS styles
import "./App.css";

// Helper function to get data from localStorage or set it if it doesn't exist
const getVotesFromStorage = () => {
  const data = localStorage.getItem("votes");
  return data ? JSON.parse(data) : { yes: 0, no: 0, total: 0 };
};

const updateVotesInStorage = (yesCount, noCount, totalCount) => {
  const votes = { yes: yesCount, no: noCount, total: totalCount };
  localStorage.setItem("votes", JSON.stringify(votes));
};

// List of delivery people and their contact information
const deliveryPeople = [
  { name: "John Doe", phone: "123-456-7890" },
  { name: "Jane Smith", phone: "987-654-3210" },
  { name: "Mike Johnson", phone: "555-678-1234" },
];

// Function to reset votes at 3 AM daily
const resetVotesAt3AM = () => {
  const now = new Date();
  const resetTime = new Date(now);
  resetTime.setHours(3, 0, 0, 0); // Set to 3 AM today

  // If the reset time has already passed today, set it to 3 AM the next day
  if (now > resetTime) {
    resetTime.setDate(resetTime.getDate() + 1);
  }

  const timeUntilReset = resetTime - now;

  setTimeout(() => {
    updateVotesInStorage(0, 0, 0); // Reset the votes at 3 AM
    window.location.reload(); // Reload to reset the vote counts
  }, timeUntilReset);
};

const App = () => {
  const [votes, setVotes] = useState(getVotesFromStorage);
  const [showNumbers, setShowNumbers] = useState({});
  const [surveyCompleted, setSurveyCompleted] = useState(false);

  // Update the vote percentages every time the state is updated
  const updateVotePercentages = () => {
    const { yes, no, total } = votes;
    const yesPercent = total === 0 ? 0 : ((yes / total) * 100).toFixed(1);
    const noPercent = total === 0 ? 0 : ((no / total) * 100).toFixed(1);
    return { yesPercent, noPercent };
  };

  // SurveyJS Form setup
  const surveyJson = {
    title: "Is Bobo’s Truck Out?",
    questions: [
      {
        type: "radiogroup",
        name: "truckStatus",
        title: "Is he out?",
        choices: ["Yes", "No"],
      },
    ],
  };

  // When a response is submitted, update the vote counts in localStorage
  const onSurveyComplete = (survey) => {
    const today = new Date().getDay(); // Sunday = 0, ..., Saturday = 6
    if (today < 5 || today > 6) {
      alert("Voting is only allowed on Friday and Saturday!");
      return; // Prevent voting if it's not Friday or Saturday
    }

    const answer = survey.data.truckStatus;
    let yesCount = votes.yes;
    let noCount = votes.no;
    let totalCount = votes.total + 1;

    if (answer === "Yes") {
      yesCount++;
    } else {
      noCount++;
    }

    setVotes({ yes: yesCount, no: noCount, total: totalCount });
    updateVotesInStorage(yesCount, noCount, totalCount);

    // Set survey as completed to display results
    setSurveyCompleted(true);
  };

  // Toggle show number for delivery people
  const toggleShowNumber = (name) => {
    setShowNumbers((prev) => ({
      ...prev,
      [name]: !prev[name],
    }));
  };

  // Run the resetVotesAt3AM function to reset votes daily
  useEffect(() => {
    resetVotesAt3AM();
  }, []);

  return (
    <div className="container">
      <h1>Bobo's Chicken Tracker</h1>

      {!surveyCompleted ? (
        // Show Survey if not completed
        <Survey.Survey json={surveyJson} onComplete={onSurveyComplete} />
      ) : (
        // Show Result if survey is completed
        <>
          <h2>Results:</h2>
          <p>Yes: {updateVotePercentages().yesPercent}%</p>
          <p>No: {updateVotePercentages().noPercent}%</p>
        </>
      )}

      <p className="info">
        *Bobo’s truck is usually out on Friday and Saturday nights when the weather is good.*
      </p>
      <p className="location">📍 1433 NE 23rd St, Oklahoma City, OK 73111</p>

      {/* Menu Section */}
      <div className="menu-section">
        <h2>Menu</h2>
        <img src="https://i.imgur.com/lXn7aCr.jpeg" alt="Bobo's Menu" className="menu-image" />
      </div>

      {/* Delivery Section */}
      <div className="delivery-section">
        <h2>Delivery Contacts</h2>
        {deliveryPeople.map((person, index) => (
          <div key={index} className="delivery-person">
            <p>{person.name}</p>
            <button className="show-number" onClick={() => toggleShowNumber(person.name)}>
              {showNumbers[person.name] ? person.phone : "Show Number"}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;
